<!-- Section: National Alert Subscription Call-to-Action (CTA) -->
<section class="w-full py-16 lg:py-24 px-margin-mobile md:px-margin bg-surface relative overflow-hidden">
<!-- Subtle glow accents -->
<div class="max-w-[1440px] mx-auto">
<div class="bg-inverse-surface text-inverse-on-surface rounded-2xl p-8 md:p-12 lg:p-16 shadow-xl relative overflow-hidden">
<!-- Atmospheric decorative gradients -->
<div class="absolute -top-32 -right-32 w-80 h-80 bg-primary-container/20 rounded-full blur-3xl pointer-events-none"></div>
<div class="absolute -bottom-32 -left-32 w-80 h-80 bg-secondary/20 rounded-full blur-3xl pointer-events-none"></div>
<div class="relative z-10 grid grid-cols-1 lg:grid-cols-12 gap-10 items-center">
<div class="lg:col-span-7 flex flex-col gap-4">
<div class="inline-flex items-center gap-2 self-start px-3 py-1 rounded-full bg-surface-container-lowest/10 text-primary-fixed font-label-sm text-label-sm uppercase tracking-wider">
<span class="w-2 h-2 rounded-full bg-primary-container animate-pulse"></span>
              Service Public Gratuit
            </div>
<h2 class="font-headline-lg text-headline-lg-mobile md:text-headline-lg text-surface-container-lowest tracking-tight">
              Soyez informé dès qu’une alerte concerne votre région
            </h2>
<p class="font-body-md text-body-md text-inverse-on-surface/80 max-w-xl leading-relaxed">
              Recevez les notifications SMS ou e-mail dès le déclenchement d'un seuil de vigilance sur vos gouvernorats favoris. Sans engagement, désinscription instantanée.
            </p>
</div>
<div class="lg:col-span-5">
<form class="bg-surface-container-lowest/10 backdrop-blur-md p-6 rounded-xl flex flex-col gap-4" id="ctaSubscriptionForm">
<div class="flex flex-col gap-1.5">
<label class="font-label-sm text-label-sm text-inverse-on-surface/90" for="govSelect">Gouvernorat prioritaire</label>
<select class="w-full px-3 py-2.5 rounded-lg bg-surface-container-lowest text-on-surface font-body-sm text-body-sm focus:outline-none" id="govSelect">
<option value="Tunis">Tunis (Nord-Est)</option>
<option value="Ariana">Ariana</option>
<option value="Ben Arous">Ben Arous</option>
<option value="Manouba">Manouba</option>
<option value="Nabeul">Nabeul</option>
<option value="Zaghouan">Zaghouan</option>
<option value="Bizerte">Bizerte</option>
<option value="Béja">Béja</option>
<option value="Jendouba">Jendouba</option>
<option value="Le Kef">Le Kef</option>
<option value="Siliana">Siliana</option>
<option value="Sousse">Sousse</option>
<option value="Monastir">Monastir</option>
<option value="Mahdia">Mahdia</option>
<option value="Sfax">Sfax</option>
<option selected="" value="Kairouan">Kairouan (Centre-Ouest)</option>
<option value="Kasserine">Kasserine</option>
<option value="Sidi Bouzid">Sidi Bouzid</option>
<option value="Gabès">Gabès</option>
<option value="Médenine">Médenine</option>
<option value="Tataouine">Tataouine</option>
<option value="Gafsa">Gafsa</option>
<option value="Tozeur">Tozeur</option>
<option value="Kébili">Kébili</option>
</select>
</div>
<div class="flex flex-col gap-1.5">
<label class="font-label-sm text-label-sm text-inverse-on-surface/90" for="contactField">Adresse e-mail ou Téléphone SMS (+216)</label>
<input class="w-full px-3 py-2.5 rounded-lg bg-surface-container-lowest text-on-surface font-body-sm text-body-sm placeholder:text-outline focus:outline-none" id="contactField" placeholder="ex: citoyen@email.tn ou 21 000 000" required="" type="text"/>
</div>
<div class="flex items-start gap-2 pt-1">
<input class="mt-1 accent-primary-container" id="consentCheck" required="" type="checkbox"/>
<label class="font-body-sm text-[12px] text-inverse-on-surface/70 leading-normal" for="consentCheck">
                  J'accepte de recevoir les bulletins d'alerte météo officielle en cas d'activation du seuil de vigilance Niveau 3 ou 4.
                </label>
</div>
<button class="w-full inline-flex items-center justify-center gap-2 bg-primary-container text-on-primary-container font-label-lg text-label-lg py-3.5 rounded-lg shadow-md hover:bg-primary hover:text-on-primary transition-all duration-200 mt-2" type="submit">
<span class="material-symbols-outlined text-[20px]">notifications_active</span>
<span>Recevoir les alertes</span>
</button>
<div class="hidden text-center text-label-sm font-label-sm text-primary-fixed pt-1" id="subscriptionFeedback">
                Abonnement confirmé ! Vous recevrez les bulletins de vigilance pour Kairouan.
              </div>
</form>
</div>
</div>
</div>
</div>
</section>
<!-- Interactive Logic for Filtering, Map Clicks & Live States -->
<script>
    (function () {
      // Map data lookup
      const governoratesData = {
        Tunis: { temp: "34°C", feels: "37°C", status: "Vigilance", level: 2, bgClass: "bg-tertiary-container", region: "Nord-Est", textClass: "text-on-tertiary-container", humidity: "48%", wind: "22 km/h", uv: "8" },
        Bizerte: { temp: "31°C", feels: "33°C", status: "Normal", level: 1, bgClass: "bg-[#22A06B]", region: "Nord", textClass: "text-white", humidity: "58%", wind: "18 km/h", uv: "7" },
        Nabeul: { temp: "33°C", feels: "36°C", status: "Vigilance", level: 2, bgClass: "bg-tertiary-container", region: "Cap Bon", textClass: "text-on-tertiary-container", humidity: "52%", wind: "20 km/h", uv: "8" },
        Jendouba: { temp: "38°C", feels: "41°C", status: "Alerte", level: 3, bgClass: "bg-primary-container", region: "Nord-Ouest", textClass: "text-on-primary-container", humidity: "26%", wind: "30 km/h", uv: "9" },
        "Le Kef": { temp: "37°C", feels: "39°C", status: "Vigilance", level: 2, bgClass: "bg-tertiary-container", region: "Nord-Ouest", textClass: "text-on-tertiary-container", humidity: "30%", wind: "25 km/h", uv: "8" },
        Sousse: { temp: "33°C", feels: "35°C", status: "Vigilance", level: 2, bgClass: "bg-tertiary-container", region: "Sahel", textClass: "text-on-tertiary-container", humidity: "54%", wind: "22 km/h", uv: "8" },
        Sfax: { temp: "35°C", feels: "38°C", status: "Vigilance", level: 2, bgClass: "bg-tertiary-container", region: "Centre-Est", textClass: "text-on-tertiary-container", humidity: "45%", wind: "25 km/h", uv: "9" },
        Kairouan: { temp: "42°C", feels: "46°C", status: "Alerte Élevée", level: 4, bgClass: "bg-secondary", region: "Centre-Ouest", textClass: "text-on-secondary", humidity: "22%", wind: "45 km/h", uv: "10" },
        Kasserine: { temp: "38°C", feels: "40°C", status: "Alerte", level: 3, bgClass: "bg-primary-container", region: "Centre-Ouest", textClass: "text-on-primary-container", humidity: "24%", wind: "35 km/h", uv: "9" },
        "Sidi Bouzid": { temp: "39°C", feels: "42°C", status: "Alerte", level: 3, bgClass: "bg-primary-container", region: "Centre-Ouest", textClass: "text-on-primary-container", humidity: "25%", wind: "38 km/h", uv: "9" },
        Gafsa: { temp: "40°C", feels: "43°C", status: "Alerte", level: 3, bgClass: "bg-primary-container", region: "Sud-Ouest", textClass: "text-on-primary-container", humidity: "20%", wind: "40 km/h", uv: "10" },
        Tozeur: { temp: "43°C", feels: "47°C", status: "Alerte Élevée", level: 4, bgClass: "bg-secondary", region: "Jérid Sud-Ouest", textClass: "text-on-secondary", humidity: "18%", wind: "48 km/h", uv: "10+" },
        Kébili: { temp: "41°C", feels: "45°C", status: "Alerte", level: 3, bgClass: "bg-primary-container", region: "Sud Nefzaoua", textClass: "text-on-primary-container", humidity: "19%", wind: "42 km/h", uv: "10" },
        Gabès: { temp: "34°C", feels: "37°C", status: "Vigilance", level: 2, bgClass: "bg-tertiary-container", region: "Sud-Est", textClass: "text-on-tertiary-container", humidity: "50%", wind: "24 km/h", uv: "8" },
        Médenine: { temp: "35°C", feels: "38°C", status: "Vigilance", level: 2, bgClass: "bg-tertiary-container", region: "Sud-Est", textClass: "text-on-tertiary-container", humidity: "42%", wind: "28 km/h", uv: "9" },
        Tataouine: { temp: "39°C", feels: "43°C", status: "Alerte", level: 3, bgClass: "bg-primary-container", region: "Extrême Sud", textClass: "text-on-primary-container", humidity: "21%", wind: "36 km/h", uv: "10" }
      };

      // Select element hooks
      const inspectorName = document.getElementById('inspectorGovName');
      const inspectorRegion = document.getElementById('inspectorGovRegion');
      const inspectorBadge = document.getElementById('inspectorBadge');
      const inspectorTemp = document.getElementById('inspectorTemp');
      const inspectorFeels = document.getElementById('inspectorFeelsLike');
      const mapPins = document.querySelectorAll('.map-pin');
      const govSelect = document.getElementById('govSelect');
      const heroSearchInput = document.getElementById('heroSearchInput');
      const heroSearchBtn = document.getElementById('heroSearchBtn');
      const regionFilterInput = document.getElementById('regionFilterInput');
      const filterBtns = document.querySelectorAll('.filter-btn');

      // Update Inspector panel
      function selectGov(govName) {
        const data = governoratesData[govName];
        if (!data) return;

        inspectorName.textContent = govName;
        inspectorRegion.textContent = 'Région ' + data.region;
        inspectorTemp.textContent = data.temp.replace('°C', '');
        inspectorFeels.textContent = data.feels;

        // Badge styling
        inspectorBadge.className = `inline-flex items-center gap-1.5 px-3 py-1 rounded-full ${data.bgClass} ${data.textClass} font-label-sm text-label-sm font-bold`;
        inspectorBadge.innerHTML = `<span class="w-2 h-2 rounded-full bg-surface-container-lowest animate-pulse"></span> ${data.status}`;

        // Sync dropdown if exists
        if (govSelect) {
          const opt = Array.from(govSelect.options).find(o => o.value.toLowerCase() === govName.toLowerCase());
          if (opt) govSelect.value = opt.value;
        }

        // Visual indicator on pin
        mapPins.forEach(p => {
          if (p.getAttribute('data-gov') === govName) {
            p.classList.add('selected-pin');
          } else {
            p.classList.remove('selected-pin');
          }
        });
      }

      // Pin clicks
      mapPins.forEach(pin => {
        pin.addEventListener('click', function () {
          const gov = this.getAttribute('data-gov');
          selectGov(gov);
        });
      });

      // Filter Buttons
      filterBtns.forEach(btn => {
        btn.addEventListener('click', function () {
          filterBtns.forEach(b => {
            b.classList.remove('bg-on-surface', 'text-on-primary');
            b.classList.add('bg-surface-container-low', 'text-on-surface');
          });
          this.classList.remove('bg-surface-container-low', 'text-on-surface');
          this.classList.add('bg-on-surface', 'text-on-primary');

          const filter = this.getAttribute('data-filter');
          mapPins.forEach(pin => {
            const level = pin.getAttribute('data-level');
            if (filter === 'all') {
              pin.style.display = '';
            } else if (filter === 'normal' && level === '1') {
              pin.style.display = '';
            } else if (filter === 'vigilance' && level === '2') {
              pin.style.display = '';
            } else if (filter === 'alerte' && level === '3') {
              pin.style.display = '';
            } else if (filter === 'critique' && level === '4') {
              pin.style.display = '';
            } else {
              pin.style.display = 'none';
            }
          });
        });
      });

      // Filter by text typing
      if (regionFilterInput) {
        regionFilterInput.addEventListener('input', function (e) {
          const query = e.target.value.toLowerCase().trim();
          mapPins.forEach(pin => {
            const gov = pin.getAttribute('data-gov').toLowerCase();
            if (gov.includes(query)) {
              pin.style.display = '';
            } else {
              pin.style.display = 'none';
            }
          });
        });
      }

      // Hero search execution
      function handleHeroSearch() {
        const val = heroSearchInput.value.trim();
        if (!val) return;
        const match = Object.keys(governoratesData).find(k => k.toLowerCase().includes(val.toLowerCase()));
        if (match) {
          selectGov(match);
          const mapSec = document.getElementById('carte-alertes');
          if (mapSec) mapSec.scrollIntoView({ behavior: 'smooth' });
        }
      }

      if (heroSearchBtn) heroSearchBtn.addEventListener('click', handleHeroSearch);
      if (heroSearchInput) {
        heroSearchInput.addEventListener('keydown', function (e) {
          if (e.key === 'Enter') handleHeroSearch();
        });
      }

      // State Simulator Helper button (Empty state / Normal state demonstration)
      const toggleDemoBtn = document.getElementById('toggleDemoStateBtn');
      let isSimulated = false;
      if (toggleDemoBtn) {
        toggleDemoBtn.addEventListener('click', function () {
          isSimulated = !isSimulated;
          if (isSimulated) {
            this.innerHTML = '<span class="material-symbols-outlined text-[16px]">check_circle</span> <span class="hidden sm:inline">Normalisé</span>';
            selectGov('Bizerte');
          } else {
            this.innerHTML = '<span class="material-symbols-outlined text-[16px]">sync_alt</span> <span class="hidden sm:inline">Simuler état</span>';
            selectGov('Kairouan');
          }
        });
      }

      // Form subscription micro-interaction
      const ctaForm = document.getElementById('ctaSubscriptionForm');
      const feedback = document.getElementById('subscriptionFeedback');
      if (ctaForm) {
        ctaForm.addEventListener('submit', function (e) {
          e.preventDefault();
          if (feedback) {
            const gov = document.getElementById('govSelect').value;
            feedback.textContent = `Abonnement validé ! Alertes actives pour le gouvernorat de ${gov}.`;
            feedback.classList.remove('hidden');
            setTimeout(() => {
              feedback.classList.add('hidden');
            }, 6000);
          }
        });
      }

      // Governorate quick button in inspector
      const subscribeGovBtn = document.getElementById('subscribeGovBtn');
      if (subscribeGovBtn) {
        subscribeGovBtn.addEventListener('click', function () {
          const currentGov = inspectorName.textContent;
          if (govSelect) govSelect.value = currentGov;
          const cta = document.getElementById('ctaSubscriptionForm');
          if (cta) cta.scrollIntoView({ behavior: 'smooth' });
        });
      }
    })();
  </script>
